contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: attempts to schedule an operation and checks general rule
    // params: target, value, data, predecessor, salt, delay
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        // read min delay and timestamp before
        uint256 minDelayBefore = c.getMinDelay();
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        uint256 tsBefore = c.getTimestamp(id);

        // try to schedule; we must call as msg.sender = this contract (it is), and this contract must have PROPOSER_ROLE
        // call and capture whether it reverted
        bool reverted;
        try c.schedule(target, value, data, predecessor, salt, delay) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 tsAfter = c.getTimestamp(id);

        // General rule asserted for all inputs:
        // If delay < minDelayBefore then schedule must revert and timestamp unchanged.
        // If delay >= minDelayBefore then schedule must NOT revert and timestamp becomes > block.timestamp (i.e., pending) and > 1.
        // Use available public observations: minDelayBefore, tsBefore, tsAfter, and reverted.
        if (delay < minDelayBefore) {
            assert(reverted && tsAfter == tsBefore);
        } else {
            // when scheduling succeeds, timestamp must change to a value > _DONE_TIMESTAMP (1)
            // and must be >= block.timestamp (we cannot read block.timestamp after call separately, but we can assert tsAfter > 1 and tsAfter != tsBefore and !reverted)
            assert(!reverted && tsAfter > 1 && tsAfter != tsBefore);
        }
    }

    receive() external payable {}
}

