contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that attempts to schedule an operation and checks the invariants
    // Inputs: a target address, value, data, predecessor, salt, and a delay to schedule with.
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        // must have enough balance if we forward value when executing call in timelock later
        // we'll not send Ether to c in schedule, but keep standard precondition true
        require(true);

        // Ensure caller (this contract) has PROPOSER_ROLE on c by calling constructor of c assigned proposer list
        // The test environment deploys c with proposers including address(this). We don't require here.

        // Compute id to schedule
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // read minDelay before scheduling
        uint256 minDelay = c.getMinDelay();

        // Only attempt to schedule when provided delay is >= minDelay to avoid revert
        // but we must allow arbitrary inputs; so if delay < minDelay we expect schedule to revert.
        bool reverted;
        if (delay < minDelay) {
            // expect revert when scheduling with insufficient delay
            try c.schedule(target, value, data, predecessor, salt, delay) {
                reverted = false;
            } catch {
                reverted = true;
            }
            // After a reverting schedule, the operation must not be marked as scheduled
            uint256 ts_after = c.getTimestamp(id);
            bool isOp = c.isOperation(id);
            // Assert: if schedule reverted then timestamp remains 0 and isOperation is false
            assert(reverted && ts_after == 0 && !isOp);
            return;
        }

        // When delay >= minDelay, schedule must succeed (no revert) and set a future timestamp > 0
        // Call must be top-level statement that mutates c
        c.schedule(target, value, data, predecessor, salt, delay);

        // Observe timestamp and operation predicates after scheduling
        uint256 ts = c.getTimestamp(id);
        bool isOpNow = c.isOperation(id);
        bool isPending = c.isOperationPending(id);

        // General rule asserted: scheduling with sufficient delay results in timestamp > 0
        // and isOperation returns true; also isOperationPending is equivalent to timestamp > 1
        assert(ts > 0 && isOpNow && (isPending == (ts > 1)));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry performing schedule and asserting a general rule about timestamps
    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        require(true);

        // Compute operation id using public hashOperation
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // Read current minDelay and current timestamp for id before scheduling
        uint256 minDelay = c.getMinDelay();
        uint256 ts_before = c.getTimestamp(id);

        // Attempt schedule as a top-level state-changing call when delay >= minDelay, otherwise attempt anyway to observe revert
        bool reverted;
        if (delay < minDelay) {
            // call expected to revert; use try/catch as top-level statement
            try c.schedule(target, value, data, predecessor, salt, delay) {
                reverted = false;
            } catch {
                reverted = true;
            }

            // After a revert, timestamp should be unchanged (still equals ts_before) and isOperation should reflect that
            uint256 ts_after_revert = c.getTimestamp(id);
            bool isOp_after_revert = c.isOperation(id);
            // General rule for revert case: schedule reverted implies no change to timestamp and isOperation matches (>0)
            assert(reverted && ts_after_revert == ts_before && (isOp_after_revert == (ts_after_revert > 0)));
            return;
        }

        // delay >= minDelay: perform schedule (top-level state-changing call). If this reverts the try/catch will capture it.
        try c.schedule(target, value, data, predecessor, salt, delay) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe timestamp and predicates after scheduling
        uint256 ts_after = c.getTimestamp(id);
        bool isOp_after = c.isOperation(id);
        bool isPending_after = c.isOperationPending(id);

        // General rule asserted for success case: if schedule did not revert then timestamp must be set to a future time (> block.timestamp)
        // and the boolean views must be consistent: isOperation == (timestamp > 0) and isOperationPending == (timestamp > 1 && timestamp <= block.timestamp ? false : timestamp > 1)
        // We express a concise general invariant: non-revert implies timestamp > block.timestamp and the view predicates agree with the numeric timestamp.
        assert(!reverted && ts_after > block.timestamp && isOp_after == (ts_after > 0) && isPending_after == (ts_after > 1 && ts_after <= block.timestamp));
    }

    receive() external payable {}
}

