        try c.schedule(target, value, data, predecessor, salt, delay) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 ts_after = c.getTimestamp(id);

        // General rule: when delay >= minDelay and schedule is invoked by this caller, it must not revert and must set timestamp to a value strictly greater than block.timestamp.
        assert(!reverted && ts_after > block.timestamp);
    }

    receive() external payable {}
}
